From Stdlib Require Import ZArith Lia.
From SpeachesPlus Require Import LaunchGeometry.
Open Scope Z_scope.

Ltac launch_absurd :=
  unfold launchable, max_grid_x, max_grid_y, max_grid_z;
  cbn [gx gy gz]; try vm_compute; intuition lia.

Ltac launch_ok :=
  unfold launchable, max_grid_x, max_grid_y, max_grid_z;
  cbn [gx gy gz]; repeat split;
  solve [ lia | vm_compute; discriminate ].

