Definition enforced_bound_launches : Z := 22.

(* Every input-scaled axis that could leave the legal grid is in exactly one
   of the two buckets: no axis is both enforced and counterexampled, and
   none is silently in neither. *)
Definition input_scaled_hazard_axes : Z := 29.

Theorem every_hazard_axis_is_classified :
  unenforced_bound_launches + enforced_bound_launches = input_scaled_hazard_axes.
Proof. reflexivity. Qed.
